import heapq
from collections import defaultdict

def maximumCount(nums, queries):
    n = len(nums)
    LIM = 100001
    is_prime = [True] * LIM
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(LIM ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, LIM, i):
                is_prime[j] = False

    m = n - 1                      # splits k = 1..n-1 map to tree positions 0..n-2
    mx = [0] * (4 * m)
    ad = [0] * (4 * m)

    def update(node, l, r, ql, qr, v):
        if ql > r or qr < l:
            return
        if ql <= l and r <= qr:
            mx[node] += v
            ad[node] += v
            return
        mid = (l + r) // 2
        update(2 * node, l, mid, ql, qr, v)
        update(2 * node + 1, mid + 1, r, ql, qr, v)
        mx[node] = max(mx[2 * node], mx[2 * node + 1]) + ad[node]

    lo = defaultdict(list)         # min-heaps of positions per prime
    hi = defaultdict(list)         # max-heaps (negated) of positions per prime
    for i, x in enumerate(nums):
        if is_prime[x]:
            lo[x].append(i)
            hi[x].append(-i)
    for p in lo:
        heapq.heapify(lo[p])
        heapq.heapify(hi[p])

    def apply(p, v):
        h = lo[p]
        while h and nums[h[0]] != p:
            heapq.heappop(h)
        if not h:
            return
        f = h[0]
        g = hi[p]
        while g and nums[-g[0]] != p:
            heapq.heappop(g)
        l = -g[0]
        if l >= 1:                 # splits k in [1, l]
            update(1, 0, m - 1, 0, l - 1, v)
        if f + 1 <= n - 1:         # splits k in [f + 1, n - 1]
            update(1, 0, m - 1, f, n - 2, v)

    for p in list(lo.keys()):
        apply(p, 1)

    ans = []
    for idx, val in queries:
        old = nums[idx]
        if old != val:
            if is_prime[old]:
                apply(old, -1)
            if is_prime[val]:
                apply(val, -1)
            nums[idx] = val
            if is_prime[val]:
                heapq.heappush(lo[val], idx)
                heapq.heappush(hi[val], -idx)
            if is_prime[old]:
                apply(old, 1)
            if is_prime[val]:
                apply(val, 1)
        ans.append(mx[1])
    return ans
